import type { VirtueFamilyKey } from "@/lib/virtues";
import { VIRTUES } from "@/lib/virtues";
import { STORY_LIBRARY } from "@/lib/chemistry-stories";

// Chemistry for Kids -- Printable Activity system.
//
// Four elements (the original pilot, below) have a hand-authored coloring
// scene and a bespoke puzzle tied to specific beats of their story. Every
// OTHER element that already has a completed story in
// lib/chemistry-stories.ts gets the same five-activity set automatically,
// generated by getActivitySet's fallback branch -- a generic decorative
// coloring page (the element's name, not a scene, since no bespoke
// illustration exists for it yet) and a generic maze puzzle labeled for
// that element. This is what lets the system scale to all 123 elements as
// their stories are written, without hand-building 123 one-off activity
// sets: only a bespoke scene/puzzle is optional, never required.
//
// Every activity is meant to be printed and used by hand -- colored,
// traced, drawn on, filled in. None of it is scored, graded, or used to
// assess a child's character. A child never needs to already "have" the
// element to do any of these; every activity works the same for every
// child, the same way every element is already available to everyone.
//
// Each element's five activities are designed to chain directly off its
// story: READ -> LISTEN -> WATCH (future animation) -> COLOR/CREATE -> NOTICE.

export type ActivityKind = "coloring" | "trace" | "draw-yourself" | "notice" | "puzzle";
export type AgeBand = "younger" | "older" | "both";
export type PuzzleKind = "matching" | "maze" | "sequence" | "card" | "maze-generic";

export type ActivityPageMeta = {
  id: string;
  kind: ActivityKind;
  title: string;
  ageBand: AgeBand;
  blurb: string;
};

export type ElementActivitySet = {
  elementSlug: string; // matches ChemistryStory.slug in lib/chemistry-stories.ts
  elementName: string;
  familyKey: VirtueFamilyKey;
  symbol: string;
  storyTitle: string;
  sceneCaption: string; // "" when there's no bespoke scene (generic fallback)
  puzzleTitle: string;
  puzzleKind: PuzzleKind;
  pages: ActivityPageMeta[];
};

function standardPages(elementName: string, puzzleTitle: string, hasScene: boolean): ActivityPageMeta[] {
  return [
    {
      id: "coloring",
      kind: "coloring",
      title: hasScene ? `Color the Story` : `Color the Word`,
      ageBand: "both",
      blurb: hasScene
        ? `A scene from ${elementName}'s story, ready to color in.`
        : `A decorative page built around ${elementName}, ready to color in.`,
    },
    {
      id: "trace",
      kind: "trace",
      title: `Trace & Color ${elementName}`,
      ageBand: "younger",
      blurb: `Big bubble letters to trace, then color in.`,
    },
    {
      id: "draw-yourself",
      kind: "draw-yourself",
      title: `Draw Yourself Using ${elementName}`,
      ageBand: "both",
      blurb: `A blank frame to draw a picture of yourself.`,
    },
    {
      id: "notice",
      kind: "notice",
      title: `Where Did You Notice ${elementName}?`,
      ageBand: "both",
      blurb: `Draw or write about where you saw it this week.`,
    },
    {
      id: "puzzle",
      kind: "puzzle",
      title: puzzleTitle,
      ageBand: "both",
      blurb: `A hands-on activity built around this element.`,
    },
  ];
}

