/** Any element with a completed story gets a full activity set -- a bespoke
 *  one for the original pilot four, a generic (but real, usable) one
 *  synthesized on the fly for every other element already in
 *  STORY_LIBRARY. Returns null only when the slug matches no story at all,
 *  since an activity set with nothing to connect back to isn't meaningful. */
export function getActivitySet(slug: string): ElementActivitySet | null {
  const bespoke = ACTIVITY_PILOT.find((a) => a.elementSlug === slug);
  if (bespoke) return bespoke;

  const story = STORY_LIBRARY.find((s) => s.slug === slug);
  if (!story) return null;
  const virtue = VIRTUES.find((v) => v.name === story.elementName);
  if (!virtue) return null;

  const puzzleTitle = `Find the Path to ${story.elementName}`;
  return {
    elementSlug: story.slug,
    elementName: story.elementName,
    familyKey: story.familyKey,
    symbol: virtue.symbol,
    storyTitle: story.title,
    sceneCaption: "",
    puzzleTitle,
    puzzleKind: "maze-generic",
    pages: standardPages(story.elementName, puzzleTitle, false),
  };
}

/** Every element that currently has a full printable activity set --
 *  the pilot four plus every other STORY_LIBRARY element, via the same
 *  fallback getActivitySet uses. Powers the activities index page without
 *  duplicating the "does this element qualify" logic. */
export function getAllActivitySets(): ElementActivitySet[] {
  return STORY_LIBRARY.map((s) => getActivitySet(s.slug)).filter(
    (a): a is ElementActivitySet => a !== null
  );
}
